from abc import ABC, abstractmethod
from typing import Any, Optional

class BaseCache(ABC):

    @abstractmethod
    def get(self, key: str) -> Optional[Any]:
        raise NotImplementedError('benchmark skeleton: not implemented')

    @abstractmethod
    def put(self, key: str, value: Any) -> None:
        raise NotImplementedError('benchmark skeleton: not implemented')

    @abstractmethod
    def delete(self, key: str) -> bool:
        raise NotImplementedError('benchmark skeleton: not implemented')

    @abstractmethod
    def size(self) -> int:
        raise NotImplementedError('benchmark skeleton: not implemented')

    @abstractmethod
    def clear(self) -> None:
        raise NotImplementedError('benchmark skeleton: not implemented')

