from collections import defaultdict, OrderedDict
from typing import Any, Optional
from .base import BaseCache


class LFUCache(BaseCache):
    """A bounded LFU cache; insertion order within a frequency is LRU order."""

    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        self.capacity = capacity
        self.key_to_val: dict[str, Any] = {}
        self.key_to_freq: dict[str, int] = {}
        self.freq_to_keys: dict[int, OrderedDict[str, None]] = defaultdict(OrderedDict)
        self.min_freq = 0

    def get(self, key: str) -> Optional[Any]:
        if key not in self.key_to_val:
            return None
        self._increment_freq(key)
        return self.key_to_val[key]

    def put(self, key: str, value: Any) -> None:
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._increment_freq(key)
            return
        if len(self.key_to_val) >= self.capacity:
            oldest = next(iter(self.freq_to_keys[self.min_freq]))
            self.freq_to_keys[self.min_freq].pop(oldest)
            del self.key_to_val[oldest]
            del self.key_to_freq[oldest]
        self.key_to_val[key] = value
        self.key_to_freq[key] = 1
        self.freq_to_keys[1][key] = None
        self.min_freq = 1

    def _increment_freq(self, key: str) -> None:
        old_freq = self.key_to_freq[key]
        bucket = self.freq_to_keys[old_freq]
        del bucket[key]
        if not bucket and self.min_freq == old_freq:
            self.min_freq = old_freq + 1
        new_freq = old_freq + 1
        self.key_to_freq[key] = new_freq
        self.freq_to_keys[new_freq][key] = None

    def delete(self, key: str) -> bool:
        if key not in self.key_to_val:
            return False
        freq = self.key_to_freq.pop(key)
        del self.key_to_val[key]
        del self.freq_to_keys[freq][key]
        if not self.key_to_val:
            self.min_freq = 0
        elif freq == self.min_freq and not self.freq_to_keys[freq]:
            self.min_freq = min(self.freq_to_keys)
        return True

    def size(self) -> int:
        return len(self.key_to_val)

    def clear(self) -> None:
        self.key_to_val.clear()
        self.key_to_freq.clear()
        self.freq_to_keys.clear()
        self.min_freq = 0

