import time
from typing import Any, Optional
from .base import BaseCache


class TTLCache(BaseCache):
    """A bounded cache whose entries expire and whose overflow evicts soonest expiry."""

    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0) -> None:
        if capacity <= 0:
            raise ValueError("Capacity must be positive")
        if default_ttl_seconds < 0:
            raise ValueError("TTL must not be negative")
        self.capacity = capacity
        self.default_ttl = default_ttl_seconds
        self.entries: dict[str, tuple[Any, float]] = {}

    def get(self, key: str) -> Optional[Any]:
        entry = self.entries.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if expires_at <= time.time():
            del self.entries[key]
            return None
        return value

    def put(self, key: str, value: Any, ttl_seconds: Optional[float] = None) -> None:
        ttl = self.default_ttl if ttl_seconds is None else ttl_seconds
        if ttl < 0:
            raise ValueError("TTL must not be negative")
        self._prune_expired()
        self.entries[key] = (value, time.time() + ttl)
        while len(self.entries) > self.capacity:
            oldest_key = min(self.entries, key=lambda item: self.entries[item][1])
            del self.entries[oldest_key]

    def delete(self, key: str) -> bool:
        if key not in self.entries:
            return False
        del self.entries[key]
        return True

    def clear(self) -> None:
        self.entries.clear()

    def size(self) -> int:
        self._prune_expired()
        return len(self.entries)

    def _prune_expired(self) -> None:
        now = time.time()
        expired = [key for key, (_, expires_at) in self.entries.items() if expires_at <= now]
        for key in expired:
            del self.entries[key]
